@extends('layouts.app') @section('title','Your bag · '.$brand) @section('content')<h1 class="section-title mb-9">Your bag</h1>@forelse($items as $item)<div class="card p-5 mb-3 flex gap-5 items-center flex-wrap"><a class="w-24 shrink-0" href="{{route('product',$item->variant->product)}}"><div class="photo">@if($item->variant->product->images->first())<img src="{{asset('storage/'.$item->variant->product->images->first()->path)}}" alt="{{$item->variant->product->images->first()->alt}}">@endif</div></a><div class="grow"><h2 class="serif text-xl">{{$item->variant->product->name}}</h2><p class="muted text-sm">{{$item->variant->sku}} · {{implode(' / ',array_filter([$item->variant->size,$item->variant->colour,$item->variant->set_size]))}}</p><p class="price mt-2">₹{{number_format($item->variant->price_paise/100,2)}}</p></div><form method="post" action="{{route('cart.update',$item)}}" class="flex items-center gap-2">@csrf @method('PATCH')<label for="qty_{{$item->id}}">Qty</label><input class="field w-20" type="number" min="1" max="20" id="qty_{{$item->id}}" name="quantity" value="{{$item->quantity}}"><button class="underline text-sm">Update</button></form><form method="post" action="{{route('cart.delete',$item)}}">@csrf @method('DELETE')<button class="underline text-sm">Remove</button></form></div>@empty<p class="card p-10">Your bag is empty. <a class="underline" href="{{route('shop')}}">Explore jewellery</a></p>@endforelse @if($items->count())<div class="text-right mt-8"><p class="serif text-2xl">Subtotal ₹{{number_format($items->sum(fn($i)=>$i->variant->price_paise*$i->quantity)/100,2)}}</p><p class="muted text-sm mt-2">Shipping, discounts and tax calculated at checkout.</p><a class="button mt-5" href="{{route('checkout')}}">Continue to checkout</a></div>@endif @endsection
